
from pydantic import BaseModel, Field
from typing import Literal
class MQTT(BaseModel):
    host:str=""
    port:int=Field(1883,ge=1,le=65535)
class Config(BaseModel):
    connection:Literal["usb","ethernet"]="usb"
    serial_port:str="/dev/ttyUSB0"
    cni_host:str=""
    cni_port:int=10001
    discovery:bool=True
    mqtt:MQTT=MQTT()
